'use strict';
function initKingdom(){state.kingdom??={};const k=state.kingdom;k.caravans??=[];k.fleet??=[];k.shipQueue??=[];k.nextId??=1;k.taxClock??=0;k.uiClock??=0;k.caravans=k.caravans.filter(c=>!c.done);k.fleet=k.fleet.filter(s=>s.hp>0);for(const s of k.fleet)s.passengers??=[]}
function castleBuilding(){return state.buildings.find(b=>b.type==='start')}
function castleLevel(){return castleBuilding()?.castleLevel||0}
function mountedSpeed(u){return u.kind==='cavalry'?1.8:1}
function kingdomArmyAway(){const k=state.kingdom;return k?k.fleet.reduce((n,s)=>n+s.passengers.length,0)+k.caravans.reduce((n,c)=>n+c.escorts.length,0):0}
function upgradeCastle(){const b=castleBuilding(),level=castleLevel();if(!b||!state.settled||level>=2){say('Najpierw załóż osadę. Zamek ma maksymalnie 2 poziomy.');return false}if((b.hp??buildingMaxHp(b))<buildingMaxHp(b)){say('Najpierw napraw domek.');return false}if(state.war.raids.some(r=>{const p=routePosition(r);return Math.hypot(p.x/T-b.x,p.y/T-b.y)<8})){say('Najpierw odeprzyj najazd w pobliżu domku.');return false}const cost=level?{wood:180,stone:160,gold:180}:{wood:120,stone:80,gold:100};if(state.wood<cost.wood||state.stone<cost.stone||state.gold<cost.gold){say('Brakuje surowców na rozbudowę siedziby.');return false}state.wood-=cost.wood;state.stone-=cost.stone;state.gold-=cost.gold;b.castleLevel=level+1;b.hp=buildingMaxHp(b);if(level===1){const p=nearbySpot(b.x,b.y+1)||{x:b.x,y:b.y};state.kingdom.king={x:(p.x+.5)*T,y:(p.y+.5)*T,wait:0,path:[]}}warLog(level?'Powstał królewski zamek! Król zamieszkał w Twojej osadzie.':'Domek rozbudowany w dwór obronny.');save();ui();renderKingdom();return true}
function recruitCavalry(){if(!state.settled||!ownCount('stajnia')||!ownCount('werbunek')){say('Kawaleria wymaga stajni i biura werbunkowego.');return false}if(armyTotal()>=armyCapacity()){say('Brak miejsc w wojsku.');return false}if(state.wood<30||state.stone<5||state.food<30||state.gold<20){say('Jeździec wymaga 30 drewna, 5 kamienia, 30 żywności i 20 monet.');return false}state.wood-=30;state.stone-=5;state.food-=30;state.gold-=20;state.war.queue.push({kind:'cavalry',remaining:14});warLog('Jeździec rozpoczął szkolenie w stajni (14 s).');save();ui();renderKingdom();return true}
function revealKingdomAt(x,y,r=2){for(let dx=-r;dx<=r;dx++)for(let dy=-r;dy<=r;dy++){const nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<N&&ny<N&&dx*dx+dy*dy<=r*r)seen.add(tileKey(nx,ny))}}
function territoryAt(x,y){const o=villageOrigin();if(state.settled&&Math.hypot(x-o.x,y-o.y)<=10+castleLevel()*2)return 'home';return state.towns.find(t=>t.relation==='conquered'&&Math.hypot(x-t.x,y-t.y)<=8)?.id||null}
function collectTribute(){let total=0;for(const t of state.towns.filter(t=>t.relation==='conquered')){const resource=t.tributeResource||['wood','stone','food'][Math.floor(hash(t.x,t.y)*3)],room=Math.max(0,capacity()-state[resource]),amount=Math.min(room,t.tributeStock||0);state[resource]+=amount;t.tributeStock=(t.tributeStock||0)-amount;total+=amount}if(total){warLog('Dostarczono daninę: '+total+' sztuk surowców.');save();ui()}else say('Nie ma daniny do odebrania albo składy są pełne.');return total}
function setTribute(id,key){const t=state.towns.find(t=>t.id===id&&t.relation==='conquered');if(!t||!['wood','stone','food'].includes(key))return false;if(t.tributeStock>0){say('Odbierz zapasy przed zmianą rodzaju daniny.');return false}t.tributeResource=key;save();renderKingdom();return true}
function updateTerritories(dt){const k=state.kingdom;for(const t of state.towns)if(t.relation==='conquered'&&!t.territoryRevealed){t.territoryRevealed=true;revealKingdomAt(t.x,t.y,8)}k.taxClock+=dt;if(k.taxClock>=30){const cycles=Math.floor(k.taxClock/30);k.taxClock%=30;const towns=state.towns.filter(t=>t.relation==='conquered');for(const t of towns)t.tributeStock=Math.min(40,(t.tributeStock||0)+4*cycles);if(towns.length){for(const t of towns){const resource=t.tributeResource||['wood','stone','food'][Math.floor(hash(t.x,t.y)*3)],amount=Math.min(Math.max(0,capacity()-state[resource]),t.tributeStock);state[resource]+=amount;t.tributeStock-=amount}save();ui()}}}
function portWater(){for(const b of state.buildings.filter(b=>b.type==='port'))for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(navalWalkable(b.x+dx,b.y+dy))return {x:b.x+dx,y:b.y+dy};return null}
function navalWalkable(x,y){if(terrain(x,y)!=='water')return false;const b=building(x,y);return b?.type!=='palisada'&&!(b?.type==='brama'&&!b.open)}
function waterRoute(from,to){const sx=Math.floor(from.x),sy=Math.floor(from.y),gx=Math.floor(to.x),gy=Math.floor(to.y);if(!navalWalkable(sx,sy)||!navalWalkable(gx,gy))return null;const q=[[gx,gy]],parent=new Map([[tileKey(gx,gy),null]]);for(let i=0;i<q.length;i++){const [x,y]=q[i];if(x===sx&&y===sy){let p=[x,y],route=[];while(p){route.push({x:p[0]+.5,y:p[1]+.5});p=parent.get(tileKey(...p))}return route}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,key=tileKey(nx,ny);if(!parent.has(key)&&navalWalkable(nx,ny)){parent.set(key,[x,y]);q.push([nx,ny])}}}return null}
function buildWarship(){const k=state.kingdom,p=portWater();if(!state.settled||!p){say('Zbuduj port przy dostępnym brzegu rzeki.');return false}if(k.fleet.length+k.shipQueue.length>=ownCount('port')*3){say('Każdy port utrzymuje 3 statki.');return false}if(state.wood<80||state.stone<20||state.gold<50||state.food<10){say('Statek wymaga 80 drewna, 20 kamienia, 50 monet i 10 żywności.');return false}state.wood-=80;state.stone-=20;state.gold-=50;state.food-=10;k.shipQueue.push({remaining:15});warLog('Budowa statku wojennego: 15 s.');save();ui();renderKingdom();return true}
function loadShip(id){const s=state.kingdom.fleet.find(s=>s.id===id);if(!s||s.passengers.length>=4)return false;syncGarrisonActors();const units=state.war.guards.filter(u=>Math.hypot(u.x-s.x,u.y-s.y)<=5*T).slice(0,4-s.passengers.length);if(!units.length){say('Podejdź żołnierzami na 5 pól od statku, używając rozkazu Idź.');return false}for(const u of units){delete u.order;u.path=[];s.passengers.push(u)}state.war.guards=state.war.guards.filter(u=>!units.includes(u));state.war.soldiers-=units.length;warLog('Zaokrętowano '+units.length+' żołnierzy. Statek mieści 4.');save();ui();renderKingdom();return true}
function unloadShip(id){const s=state.kingdom.fleet.find(s=>s.id===id);if(!s?.passengers.length)return false;const positions=[];for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const x=Math.floor(s.x/T)+dx,y=Math.floor(s.y/T)+dy;if(Math.hypot(x+.5-s.x/T,y+.5-s.y/T)<=2.3&&npcWalkable(x,y)&&!foreignBuilding(x,y))positions.push({x,y})}positions.sort((a,b)=>Math.hypot(a.x-s.x/T,a.y-s.y/T)-Math.hypot(b.x-s.x/T,b.y-s.y/T));if(!positions.length){say('Dopłyń do dostępnego brzegu, aby wysadzić desant.');return false}syncGarrisonActors();const passengers=s.passengers.splice(0);for(let i=0;i<passengers.length;i++){const p=positions[i%positions.length],u=passengers[i];state.war.guards.push({...u,x:(p.x+.5)*T,y:(p.y+.5)*T,home:p,path:[],order:null});revealKingdomAt(p.x,p.y,3)}state.war.soldiers+=passengers.length;delete s.landing;warLog('Desant: '+passengers.length+' żołnierzy na brzegu. Możesz wydać im rozkazy.');save();ui();renderKingdom();return true}
let kingdomTab='castle',kingdomSignature='',navalDraft=null;
function beginNavalOrder(id,kind){if(!state.kingdom.fleet.some(s=>s.id===id)||!['move','land'].includes(kind))return false;cancelCommand();cancelPatrolDraft();setMode(null);navalDraft={id,kind};$('kingdomPanel').classList.add('hidden');$('navalOrder').style.display='flex';$('navalOrderText').textContent=kind==='land'?'Desant: kliknij odkryty brzeg':'Flota: kliknij odkrytą wodę';say(kind==='land'?'Kliknij dostępny brzeg. Statek dopłynie i wysadzi żołnierzy.':'Wskaż cel na rzece. Statek automatycznie ostrzeliwuje wrogów na wodzie.');return true}
function cancelNavalOrder(){navalDraft=null;$('navalOrder').style.display='none'}
function chooseNavalPoint(x,y){if(!navalDraft)return false;const s=state.kingdom.fleet.find(s=>s.id===navalDraft.id);if(!s){cancelNavalOrder();return false}if(!seen.has(tileKey(x,y))){say('Najpierw odkryj to miejsce.');return false}let route=null,landing=null;if(navalDraft.kind==='land'){if(!npcWalkable(x,y)||foreignBuilding(x,y)){say('Wskaż dostępny ląd przy rzece.');return false}for(let dx=-1;dx<=1&&!route;dx++)for(let dy=-1;dy<=1;dy++)if(Math.abs(dx)+Math.abs(dy)===1){route=waterRoute({x:s.x/T,y:s.y/T},{x:x+dx,y:y+dy});if(route){landing={x,y};break}}}else route=waterRoute({x:s.x/T,y:s.y/T},{x,y});if(!route){say('Brak wodnego połączenia. Sprawdź zapory i bramy na rzece.');return false}s.route=route;s.progress=0;s.destination=route[route.length-1];s.landing=landing;s.waiting=false;s.retry=0;cancelNavalOrder();warLog(landing?'Statek płynie na desant.':'Wydano rozkaz flocie.');save();return true}
function updateFleet(dt){const k=state.kingdom;if(k.shipQueue.length&&portWater()){k.shipQueue[0].remaining-=dt;if(k.shipQueue[0].remaining<=0){k.shipQueue.shift();const p=portWater();k.fleet.push({id:'ship-'+k.nextId++,x:(p.x+.5)*T,y:(p.y+.5)*T,hp:60,passengers:[],cooldown:0});warLog('Statek wojenny gotowy w porcie.');save()}}
 for(const s of [...k.fleet]){s.cooldown=Math.max(0,(s.cooldown||0)-dt);if(s.route&&s.progress<s.route.length-1){const next=s.route[Math.min(s.route.length-1,Math.floor(s.progress)+1)];if(!navalWalkable(Math.floor(next.x),Math.floor(next.y))){s.waiting=true;s.retry=(s.retry||0)-dt;if(s.retry<=0){s.retry=5;const route=waterRoute({x:s.x/T,y:s.y/T},s.destination);if(route){s.route=route;s.progress=0;s.waiting=false}}}else{s.waiting=false;s.progress=Math.min(s.route.length-1,s.progress+dt*2.8);const p=routePosition(s);s.x=p.x;s.y=p.y}}if(s.landing&&(!s.route||s.progress>=s.route.length-1)){s.unloadRetry=(s.unloadRetry||0)-dt;if(s.unloadRetry<=0){s.unloadRetry=2;unloadShip(s.id)}}
 const target=state.war.raids.filter(r=>r.power>0).map(r=>({r,p:routePosition(r)})).filter(({p})=>terrain(Math.floor(p.x/T),Math.floor(p.y/T))==='water'&&Math.hypot(p.x-s.x,p.y-s.y)<6*T).sort((a,b)=>Math.hypot(a.p.x-s.x,a.p.y-s.y)-Math.hypot(b.p.x-s.x,b.p.y-s.y))[0];if(target){s.hp=Math.max(0,s.hp-dt*1.5);if(s.cooldown<=0){s.cooldown=1.8;target.r.power=Math.max(0,target.r.power-5);target.r.lastHit=state.time;s.shot={x:s.x,y:s.y-20,tx:target.p.x,ty:target.p.y-15,time:state.time}}}if(s.hp<=0){k.fleet=k.fleet.filter(o=>o!==s);warLog('Zatonął statek. Stracono załadowanych żołnierzy: '+s.passengers.length+'.');save()}revealKingdomAt(Math.floor(s.x/T),Math.floor(s.y/T),3)}
}
function caravanRoute(from,to){const u={x:(from.x+.5)*T,y:(from.y+.5)*T},goal=nearestApproach(u,to.x,to.y,2);if(!goal)return null;const path=findRoute(u,goal,true);return path===null?null:[{x:from.x+.5,y:from.y+.5},...path.map(p=>({x:p.x/T,y:p.y/T}))]}
function sendCaravan(id,escorts=0,key='wood'){const t=state.towns.find(t=>t.id===id),k=state.kingdom,market=state.buildings.find(b=>b.type==='targ');if(!state.settled||!market||!t?.discovered||!['neutral','allied','conquered'].includes(t.relation)){say('Karawana wymaga targu i odkrytej osady, z którą nie prowadzisz wojny.');return false}if(![0,1,2].includes(escorts)||!['wood','stone','food'].includes(key))return false;if(k.caravans.length>=ownCount('targ')*3){say('Targ obsługuje 3 karawany naraz.');return false}if(state[key]<20){say('Potrzebujesz 20 sztuk towaru.');return false}const start=nearbySpot(market.x,market.y+1);if(!start)return false;syncGarrisonActors();const available=state.war.guards.filter(u=>Math.hypot(u.x/T-start.x-.5,u.y/T-start.y-.5)<6).slice(0,escorts);if(available.length!==escorts){say('Podejdź eskortą do targu (6 pól).');return false}const route=caravanRoute(start,t);if(!route){say('Brak drogi dla wozu. Usuń drzewa, zbuduj mosty i otwórz bramy.');return false}state[key]-=20;for(const u of available){delete u.order;u.path=[]}state.war.guards=state.war.guards.filter(u=>!available.includes(u));state.war.soldiers-=escorts;const reward=MARKET_GOODS[key].sell*2+Math.min(50,Math.floor(Math.hypot(t.x-start.x,t.y-start.y)/5));k.caravans.push({id:'caravan-'+k.nextId++,townId:id,route,progress:0,phase:'outbound',resource:key,cargo:20,reward,goldCargo:0,escorts:available,hp:50,origin:start,naval:false});warLog('Karawana do '+t.name+': 20 towaru, eskorta '+escorts+'. Zapłata po powrocie: '+reward+' monet.');save();ui();renderKingdom();return true}
function turnCaravan(c,phase){const p=routePosition(c);c.route=[{x:p.x/T,y:p.y/T},...c.route.slice(0,Math.floor(c.progress)+1).reverse()];c.progress=0;c.phase=phase;c.waiting=false;c.retry=0}
function recallCaravan(id){const c=state.kingdom.caravans.find(c=>c.id===id);if(!c||c.phase!=='outbound')return false;turnCaravan(c,'recall');warLog('Karawana zawraca z towarem i eskortą.');save();renderKingdom();return true}
function finishCaravan(c){if(!state.kingdom.caravans.includes(c))return false;state.kingdom.caravans=state.kingdom.caravans.filter(o=>o!==c);syncGarrisonActors();for(let i=0;i<c.escorts.length;i++){const p=nearbySpot(c.origin.x+i%3,c.origin.y+Math.floor(i/3))||c.origin;state.war.guards.push({...c.escorts[i],x:(p.x+.5)*T,y:(p.y+.5)*T,home:p,path:[],order:null})}state.war.soldiers+=c.escorts.length;state.gold+=c.goldCargo||0;if(c.cargo>0)state[c.resource]+=c.cargo;warLog('Karawana wróciła: '+(c.goldCargo||0)+' monet · ocalała eskorta: '+c.escorts.length+(c.cargo?' i zwrócony towar.':'.'));save();ui()}
function updateCaravans(dt){for(const c of [...state.kingdom.caravans]){const t=state.towns.find(t=>t.id===c.townId);if(c.phase==='outbound'&&(!t||t.relation==='war')){turnCaravan(c,'recall');warLog('Karawana zawraca — odbiorca jest niedostępny lub trwa wojna.');save()}let p=routePosition(c),threat=state.war.raids.filter(r=>r.power>0).find(r=>{const q=routePosition(r);return Math.hypot(q.x-p.x,q.y-p.y)<4*T});for(let i=c.escorts.length-1;i>=0;i--){const u=c.escorts[i];if(threat){defendActor(u,dt);if(u.hp<=0){c.escorts.splice(i,1);warLog('Poległ żołnierz eskorty karawany.');save()}}else{u.fighting=false;healDefender(u,dt);u.x=p.x+(i%2?18:-18);u.y=p.y+22+Math.floor(i/2)*22}}
 if(threat&&c.phase!=='retreat'){const q=routePosition(threat);if(Math.hypot(q.x-p.x,q.y-p.y)<1.8*T)c.hp=Math.max(0,c.hp-dt*4)}else{advanceCampaign(c,dt,1.5);p=routePosition(c)}if(c.hp<=0&&c.phase!=='retreat'){c.cargo=0;c.goldCargo=0;turnCaravan(c,'retreat');warLog('Karawana straciła wóz i towary. Ocalała eskorta wraca.');save()}
 if(c.progress>=c.route.length-1){if(c.phase==='outbound'){c.cargo=0;c.goldCargo=c.reward;t.marketStock??={wood:50,stone:40,food:60};t.marketStock[c.resource]=Math.min(100,t.marketStock[c.resource]+20);c.route=c.route.slice().reverse();c.progress=0;c.phase='return';warLog('Karawana sprzedała towary w '+t.name+' i wraca z '+c.reward+' monetami.');save()}else finishCaravan(c)}revealKingdomAt(Math.floor(p.x/T),Math.floor(p.y/T),2)}}
function updateKing(dt){const king=state.kingdom.king,b=castleBuilding();if(!king||!b||castleLevel()<2)return;king.wait=Math.max(0,(king.wait||0)-dt);if(!king.path?.length){if(king.wait>0)return;const phase=Math.floor(state.time/5)%4,offsets=[[0,2],[2,1],[0,-2],[-2,1]],offset=offsets[phase],p=nearbySpot(b.x+offset[0],b.y+offset[1]);king.path=p?findRoute(king,p)||[]:[];king.wait=5}const next=king.path[0];if(next){if(blocked(next.x,next.y)){king.path=[];return}const d=Math.hypot(next.x-king.x,next.y-king.y),step=35*dt;if(d<=step){king.x=next.x;king.y=next.y;king.path.shift()}else{king.x+=(next.x-king.x)/d*step;king.y+=(next.y-king.y)/d*step}}}
function updateKingdom(dt){updateTerritories(dt);updateKing(dt);updateFleet(dt);updateCaravans(dt);state.kingdom.uiClock+=dt;if(state.kingdom.uiClock>=1){state.kingdom.uiClock=0;renderKingdom()}}
function drawCavalryUnit(u){const x=u.x,y=u.y;ctx.fillStyle='#20352b55';ctx.beginPath();ctx.ellipse(x,y+10,19,7,0,0,7);ctx.fill();ctx.fillStyle='#815d3c';ctx.fillRect(x-17,y-8,33,16);const swing=typeof walkingSwing==='function'?walkingSwing(u.walkSource||u,x,y):0;ctx.strokeStyle='#815d3c';ctx.lineWidth=4;for(const [i,dx] of [-13,-6,7,13].entries()){ctx.beginPath();ctx.moveTo(x+dx,y+4);ctx.lineTo(x+dx+swing*(i%2?1:-1),y+16);ctx.stroke()}ctx.lineWidth=1;polygon([[x+8,y-5],[x+13,y-24],[x+23,y-22],[x+20,y-8]],'#98724b');ctx.fillStyle='#363b32';ctx.fillRect(x+15,y-25,9,4);drawTrooper(x-1,y-15,u.player?'#c7a05f':'#7899bd')}
function drawCastle(b,x,y){if(b.type!=='start'||!b.castleLevel)return false;const level=b.castleLevel;ctx.fillStyle='#20352b55';ctx.beginPath();ctx.ellipse(x,y+13,35,11,0,0,7);ctx.fill();ctx.fillStyle='#a8aa98';ctx.fillRect(x-27,y-32,54,45);ctx.fillStyle='#bfc1ad';for(const dx of [-31,18]){ctx.fillRect(x+dx,y-(level===2?57:44),14,57);for(let i=0;i<3;i++)ctx.fillRect(x+dx+i*5,y-(level===2?64:51),4,10)}ctx.fillStyle='#636956';ctx.fillRect(x-7,y-7,14,20);polygon([[x-24,y-33],[x,y-(level===2?66:49)],[x+24,y-33]],'#5c7464');ctx.fillStyle='#d8c66f';ctx.fillRect(x,y-(level===2?86:68),2,27);polygon([[x+2,y-(level===2?86:68)],[x+24,y-(level===2?80:62)],[x+2,y-(level===2?71:53)]],'#e1c66b');ctx.fillStyle='#e9d68c';ctx.font='10px system-ui';ctx.fillText(level===2?'ZAMEK':'DWÓR',x-18,y-76);return true}
function drawWarship(s,enemy=false){const x=s.x,y=s.y;polygon([[x-29,y-4],[x+30,y-4],[x+19,y+14],[x-18,y+14]],enemy?'#8f5143':'#6e583c');ctx.fillStyle='#d4bd8b';ctx.fillRect(x-2,y-48,3,46);polygon([[x+1,y-48],[x+1,y-11],[x+25,y-13]],enemy?'#bd7767':'#7aacc3');ctx.fillStyle='#e2cf8e';ctx.fillRect(x-21,y-11,10,8);ctx.fillRect(x+13,y-9,9,7);if(s.hp!==undefined&&s.hp<60){ctx.fillStyle='#634137';ctx.fillRect(x-24,y-62,48,4);ctx.fillStyle='#aad2a3';ctx.fillRect(x-24,y-62,48*Math.max(0,s.hp)/60,4)}drawSiegeShot(s.shot)}
function drawKingdomWorld(){const visible=p=>seen.has(tileKey(Math.floor(p.x/T),Math.floor(p.y/T))),k=state.kingdom;for(const s of k.fleet)if(visible(s)){drawWarship(s);ctx.fillStyle='#e8d594';ctx.font='10px system-ui';ctx.fillText('STATEK · '+s.passengers.length+'/4',s.x-32,s.y-69)}for(const r of state.war.raids){const p=routePosition(r);if(terrain(Math.floor(p.x/T),Math.floor(p.y/T))==='water'&&visible(p))drawWarship(p,true)}for(const c of k.caravans){const p=routePosition(c);if(visible(p)){if(c.camel&&typeof drawTradeCamel==='function'){drawTradeCamel(c,p)}else if(c.phase!=='retreat'){ctx.fillStyle='#5c4934';for(const dx of [-13,12]){ctx.beginPath();ctx.arc(p.x+dx,p.y+8,6,0,7);ctx.fill()}ctx.fillStyle='#ad8552';ctx.fillRect(p.x-20,p.y-6,40,13);ctx.fillStyle='#d1c6a0';ctx.fillRect(p.x-16,p.y-26,32,21);ctx.fillStyle='#9c976b';ctx.fillRect(p.x-14,p.y-23,28,4);ctx.fillStyle='#efdba1';ctx.font='9px system-ui';ctx.fillText('KARAWANA · '+Math.ceil(c.hp),p.x-35,p.y-34)}for(const u of c.escorts)drawBattleActor(u,'#8d9b76')}}if(k.king&&castleLevel()===2&&visible(k.king)){const u=k.king;drawTrooper(u.x,u.y,'#b9a35b',u);polygon([[u.x-7,u.y-30],[u.x-9,u.y-40],[u.x-3,u.y-36],[u.x,u.y-43],[u.x+3,u.y-36],[u.x+9,u.y-40],[u.x+7,u.y-30]],'#edcd69');ctx.fillStyle='#f1d98a';ctx.font='10px system-ui';ctx.fillText('KRÓL',u.x-13,u.y-52)}}
function drawTerritories(){if(!state.kingdom)return;ctx.save();ctx.strokeStyle='#b3cb9670';ctx.fillStyle='#b6cf8b09';ctx.lineWidth=2;const towns=state.towns.filter(t=>t.relation==='conquered');if(state.settled)towns.push({...state.settled,home:true});for(const t of towns){if(!seen.has(tileKey(t.x,t.y)))continue;ctx.beginPath();ctx.arc((t.x+.5)*T,(t.y+.5)*T,(t.home?10+castleLevel()*2:8)*T,0,7);ctx.fill();ctx.stroke()}ctx.restore()}
function drawTerritoryMini(){for(const t of state.towns.filter(t=>t.relation==='conquered')){mc.strokeStyle='#8dc5ac';mc.strokeRect((t.x-8)/N*170,(t.y-8)/N*145,16/N*170,16/N*145)}}
function kingdomTabs(){return `<div class="kingdom-tabs">${[['castle','Zamek'],['cavalry','Konnica'],['fleet','Flota'],['trade','Karawany'],['lands','Tereny']].map(([k,label])=>`<button class="${kingdomTab===k?'active':''}" data-kingdom="tab" data-value="${k}">${label}</button>`).join('')}</div>`}
function castleUI(){const level=castleLevel();return `<h3>${['Mały domek','Dwór obronny','Królewski zamek'][level]}</h3><p class="war-hint">Poziom ${level}/2. Każdy poziom daje +200 pojemności składów, +6 miejsc w wojsku i +10 obrony. Król pojawia się na poziomie 2 i spaceruje po osadzie. Rozbudowa zachowuje położenie domku.</p><button class="recruit" data-kingdom="castle" ${level>=2?'disabled':''}>${level===0?'Rozbuduj dwór · 120 🪵 80 ◆ 100 ●':level===1?'Zbuduj zamek · 180 🪵 160 ◆ 180 ●':'Zamek ukończony'}</button><p class="war-hint">Rozbudowa wymaga założonej osady, sprawnej siedziby i odparcia pobliskiego najazdu.</p>`}
function cavalryUI(){return `<h3>Kawaleria</h3><p class="war-hint">Jeździec porusza się o 80% szybciej, zadaje bazowo 3 obrażenia i ma siłę wyprawy 6. Działają na niego miecze i zbroje z kuźni. Wymaga stajni oraz biura werbunkowego; zajmuje jedno miejsce w wojsku.</p><button class="recruit" data-kingdom="cavalry" ${!ownCount('stajnia')||!ownCount('werbunek')||armyTotal()>=armyCapacity()?'disabled':''}>Szkol jeźdźca · 30 🪵 5 ◆ 30 🌾 20 ●</button><p class="war-hint">Szkolenie: 14 s. Jeźdźcy w garnizonie: ${state.war.guards.filter(u=>u.kind==='cavalry').length}. Wspólna kolejka: ${state.war.queue.length}${state.war.queue.length?' · '+Math.ceil(state.war.queue[0].remaining)+' s':''}. Rozkazy wydasz przez Dowodzenie.</p>`}
function fleetUI(){const k=state.kingdom;return `<h3>Flota rzeczna</h3><p class="war-hint">Port daje 3 miejsca na statki. Statek ostrzeliwuje wrogów na rzece na 6 pól i mieści 4 żołnierzy. Podejdź wojskiem na 5 pól, załaduj i wskaż odkryty brzeg do desantu.</p><button class="recruit" data-kingdom="ship" ${!portWater()||k.fleet.length+k.shipQueue.length>=ownCount('port')*3?'disabled':''}>Buduj statek · 80 🪵 20 ◆ 50 ● 10 🌾</button><p class="war-hint">${k.shipQueue.length?'Budowa: '+Math.ceil(k.shipQueue[0].remaining)+' s · kolejka '+k.shipQueue.length:'Budowa trwa 15 s.'}</p>${k.fleet.map((s,i)=>`<section class="town-card"><b>Statek ${i+1} · ${Math.ceil(s.hp)}/60 PŻ · desant ${s.passengers.length}/4</b><p>${s.waiting?'Czeka na wodne przejście':s.route&&s.progress<s.route.length-1?'W rejsie':'Gotowy'}</p><div class="war-actions"><button data-kingdom="sail" data-value="${s.id}">Płyń</button><button data-kingdom="load" data-value="${s.id}">Załaduj wojsko</button><button data-kingdom="land" data-value="${s.id}" ${!s.passengers.length?'disabled':''}>Desant — wskaż brzeg</button><button data-kingdom="unload" data-value="${s.id}" ${!s.passengers.length?'disabled':''}>Wyładuj tutaj</button></div></section>`).join('')}`}
function caravanUI(){const k=state.kingdom;return `<h3>Karawany i eskorta</h3><p class="war-hint">Targ daje 3 miejsca na wozy. Karawana zabiera 20 drewna, jedzie lądem przez ścieżki i mosty, a po sprzedaży wraca z monetami. Zapłata dociera dopiero z wozem. Eskorta musi czekać do 6 pól od targu; żołnierzy odzyskasz po powrocie. Wrogie najazdy mogą napaść na karawanę.</p>${k.caravans.map(c=>`<section class="town-card"><b>${state.towns.find(t=>t.id===c.townId)?.name||'Karawana'} · ${c.phase==='outbound'?'do osady':c.phase==='return'?'powrót z zapłatą':c.phase==='retreat'?'odwrót':'powrót z towarem'}</b><p>${Math.ceil(c.hp)}/50 PŻ · eskorta ${c.escorts.length} · ${c.goldCargo||0} monet na wozie${c.waiting?' · czeka na przejście':''}</p>${c.phase==='outbound'?`<button data-kingdom="recallCaravan" data-value="${c.id}">Odwołaj karawanę</button>`:''}</section>`).join('')}<small>WYŚLIJ KARAWANĘ Z DREWNEM</small>${state.towns.filter(t=>t.discovered&&t.relation!=='war').map(t=>`<section class="town-card"><b>${t.name}</b><div class="war-actions">${[0,1,2].map(n=>`<button data-kingdom="caravan" data-value="${t.id}" data-escort="${n}" ${!ownCount('targ')||state.wood<20||state.war.soldiers<n?'disabled':''}>${n?'Eskorta '+n:'Bez eskorty'}</button>`).join('')}</div></section>`).join('')}`}
function landsUI(){const towns=state.towns.filter(t=>t.relation==='conquered');return `<h3>Twoje królestwo</h3><p class="war-hint">Podbite osady: ${towns.length}. Każda obejmuje teren w promieniu 8 pól i dostarcza 4 surowce co 30 s. Danina automatycznie trafia do składów; przy braku miejsca czeka do 40 sztuk w osadzie. Dotychczasowa danina w monetach nadal działa.</p><button class="recruit" data-kingdom="tribute">Odbierz oczekującą daninę</button>${towns.map(t=>`<section class="town-card"><b>${t.name} · promień 8 pól</b><p>Zapasy: ${t.tributeStock||0} · danina: ${{wood:'drewno',stone:'kamień',food:'żywność'}[t.tributeResource||['wood','stone','food'][Math.floor(hash(t.x,t.y)*3)]]}</p><div class="war-actions">${[['wood','Drewno'],['stone','Kamień'],['food','Żywność']].map(([key,label])=>`<button data-kingdom="policy" data-value="${t.id}" data-resource="${key}">${label}</button>`).join('')}</div></section>`).join('')||'<p class="war-hint">Zdobądź osadę, wysyłając wyprawę lub atakując wojskiem na rozkaz.</p>'}`}
function renderKingdom(){if($('kingdomPanel').classList.contains('hidden'))return;const k=state.kingdom,signature=JSON.stringify([kingdomTab,castleLevel(),ownCount('stajnia'),ownCount('werbunek'),ownCount('port'),ownCount('targ'),state.wood,state.stone,state.food,state.gold,state.war.soldiers,armyTotal(),state.war.guards.map(u=>u.kind),state.war.queue.map(q=>Math.ceil(q.remaining)),k.shipQueue.map(q=>Math.ceil(q.remaining)),k.fleet.map(s=>[s.id,Math.ceil(s.hp),s.passengers.length,s.waiting,s.route&&s.progress<s.route.length-1]),k.caravans.map(c=>[c.id,c.phase,Math.ceil(c.hp),c.escorts.length,c.goldCargo,c.waiting]),state.towns.map(t=>[t.id,t.discovered,t.relation,t.tributeResource,t.tributeStock])]);if(signature===kingdomSignature)return;kingdomSignature=signature;$('kingdomContent').innerHTML=kingdomTabs()+({castle:castleUI,cavalry:cavalryUI,fleet:fleetUI,trade:caravanUI,lands:landsUI}[kingdomTab])()}
function openKingdom(tab='castle'){kingdomTab=tab;kingdomSignature='';$('strategyPanel').classList.add('hidden');$('warPanel').classList.add('hidden');$('kingdomPanel').classList.remove('hidden');renderKingdom()}
$('kingdomClose').onclick=()=>$('kingdomPanel').classList.add('hidden');$('navalOrderCancel').onclick=cancelNavalOrder;$('kingdomPanel').onclick=e=>{const b=e.target.closest('button[data-kingdom]');if(!b||b.disabled)return;const v=b.dataset.value;switch(b.dataset.kingdom){case 'tab':kingdomTab=v;break;case 'castle':upgradeCastle();break;case 'cavalry':recruitCavalry();break;case 'ship':buildWarship();break;case 'sail':beginNavalOrder(v,'move');break;case 'land':beginNavalOrder(v,'land');break;case 'load':loadShip(v);break;case 'unload':unloadShip(v);break;case 'caravan':sendCaravan(v,Number(b.dataset.escort));break;case 'recallCaravan':recallCaravan(v);break;case 'tribute':collectTribute();break;case 'policy':setTribute(v,b.dataset.resource);break}renderKingdom()};
const clickBeforeKingdom=c.onpointerdown;c.onpointerdown=e=>{if(navalDraft&&mode)cancelNavalOrder();if(navalDraft&&!mode){const p=worldPoint(e);chooseNavalPoint(Math.floor(p.x/T),Math.floor(p.y/T));return}clickBeforeKingdom(e)};window.addEventListener('keydown',e=>{if(e.key==='Escape')cancelNavalOrder()});
initKingdom();ui();
